-- Core Contract Intelligence retrack: immutable revisions, structured OUGHT, evidence/provenance,
-- reviewer-controlled Gap lifecycle, role-aware writes and append-only history.
do $$begin alter type public.gap_status add value if not exists 'Disputed';alter type public.gap_status add value if not exists 'Deferred';alter type public.gap_status add value if not exists 'Rejected';alter type public.gap_status add value if not exists 'Monitoring';alter type public.gap_status add value if not exists 'Not Applicable';exception when duplicate_object then null;end$$;
do $$begin create type public.document_processing_status as enum('queued','uploading','validating','processing','needs review','ready','partial failure','failed');exception when duplicate_object then null;end$$;

create or replace function private.org_role(org_id uuid) returns public.member_role language sql stable security definer set search_path='' as $$select m.role from public.organization_members m where m.organization_id=org_id and m.user_id=auth.uid() limit 1$$;
revoke all on function private.org_role(uuid) from public;grant execute on function private.org_role(uuid) to authenticated;
create or replace function private.can_manage_core(org_id uuid) returns boolean language sql stable security definer set search_path='' as $$select coalesce(private.org_role(org_id) in ('owner','admin','contract_manager'),false)$$;
create or replace function private.can_contribute_core(org_id uuid) returns boolean language sql stable security definer set search_path='' as $$select coalesce(private.org_role(org_id) in ('owner','admin','contract_manager','contributor','reviewer'),false)$$;
create or replace function private.can_review_core(org_id uuid) returns boolean language sql stable security definer set search_path='' as $$select coalesce(private.org_role(org_id) in ('owner','admin','contract_manager','reviewer'),false)$$;
revoke all on function private.can_manage_core(uuid) from public;revoke all on function private.can_contribute_core(uuid) from public;revoke all on function private.can_review_core(uuid) from public;
grant execute on function private.can_manage_core(uuid) to authenticated;grant execute on function private.can_contribute_core(uuid) to authenticated;grant execute on function private.can_review_core(uuid) to authenticated;

alter table public.projects add column if not exists created_by uuid references auth.users(id);
update public.projects p set created_by=o.created_by from public.organizations o where p.organization_id=o.id and p.created_by is null;
alter table public.contracts add column if not exists contract_type text,add column if not exists employer text,add column if not exists contractor text,add column if not exists consultant text,add column if not exists effective_date date,add column if not exists commencement_date date,add column if not exists completion_date date,add column if not exists governing_law text,add column if not exists status text not null default 'Active',add column if not exists created_by uuid references auth.users(id),add column if not exists updated_at timestamptz not null default now();
update public.contracts c set created_by=o.created_by from public.organizations o where c.organization_id=o.id and c.created_by is null;

create table if not exists public.document_versions(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,document_id uuid not null references public.documents(id) on delete cascade,version_no integer not null check(version_no>0),file_name text not null,storage_path text not null,mime_type text,byte_size bigint check(byte_size is null or byte_size>=0),content_hash text,processing_status public.document_processing_status not null default 'queued',processing_error text,is_current boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now(),extracted_at timestamptz,unique(document_id,version_no));
create unique index if not exists document_versions_one_current_idx on public.document_versions(document_id) where is_current;
create index if not exists document_versions_org_idx on public.document_versions(organization_id,created_at desc);
create index if not exists document_versions_status_idx on public.document_versions(organization_id,processing_status);
alter table public.documents add column if not exists current_version_id uuid references public.document_versions(id) on delete set null;
alter table public.documents add column if not exists processing_status public.document_processing_status not null default 'queued';
insert into public.document_versions(organization_id,document_id,version_no,file_name,storage_path,content_hash,processing_status,is_current,created_by,created_at)
select d.organization_id,d.id,greatest(d.version_no,1),d.file_name,d.storage_path,d.content_hash,'ready',true,d.uploaded_by,d.created_at from public.documents d where not exists(select 1 from public.document_versions v where v.document_id=d.id);
update public.documents d set current_version_id=v.id,processing_status=v.processing_status from public.document_versions v where v.document_id=d.id and v.is_current and d.current_version_id is null;

create or replace function private.guard_document_version_immutable() returns trigger language plpgsql set search_path='' as $$begin if new.organization_id is distinct from old.organization_id or new.document_id is distinct from old.document_id or new.version_no is distinct from old.version_no or new.file_name is distinct from old.file_name or new.storage_path is distinct from old.storage_path or new.mime_type is distinct from old.mime_type or new.byte_size is distinct from old.byte_size or new.content_hash is distinct from old.content_hash or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then raise exception 'document revision source fields are immutable';end if;return new;end$$;
drop trigger if exists document_versions_immutable_guard on public.document_versions;create trigger document_versions_immutable_guard before update on public.document_versions for each row execute function private.guard_document_version_immutable();

create table if not exists public.clauses(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,project_id uuid not null references public.projects(id) on delete cascade,contract_id uuid not null references public.contracts(id) on delete cascade,document_version_id uuid not null references public.document_versions(id) on delete cascade,clause_number text,heading text,clause_text text not null,source_locator text not null,page_start integer,page_end integer,confidence text check(confidence in ('High','Medium','Low')),ai_run_id uuid references public.ai_runs(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.definitions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,project_id uuid not null references public.projects(id) on delete cascade,contract_id uuid not null references public.contracts(id) on delete cascade,document_version_id uuid not null references public.document_versions(id) on delete cascade,term text not null,definition_text text not null,source_locator text not null,confidence text check(confidence in ('High','Medium','Low')),ai_run_id uuid references public.ai_runs(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.obligations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,project_id uuid not null references public.projects(id) on delete cascade,contract_id uuid not null references public.contracts(id) on delete cascade,clause_id uuid references public.clauses(id) on delete set null,document_version_id uuid not null references public.document_versions(id) on delete cascade,obligation_type text,responsible_party text,beneficiary_party text,obligation_text text not null,trigger_condition text,timing_requirement text,consequence text,source_locator text not null,status text not null default 'Open' check(status in ('Open','Satisfied','Potential Breach','Breached','Not Applicable')),confidence text check(confidence in ('High','Medium','Low')),ai_run_id uuid references public.ai_runs(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.evidence(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,project_id uuid references public.projects(id) on delete cascade,contract_id uuid references public.contracts(id) on delete cascade,document_id uuid not null references public.documents(id) on delete cascade,document_version_id uuid not null references public.document_versions(id) on delete cascade,clause_id uuid references public.clauses(id) on delete set null,obligation_id uuid references public.obligations(id) on delete set null,source_type text not null default 'document',source_locator text not null,excerpt text,evidence_kind text not null default 'source' check(evidence_kind in ('source','supporting','contradictory','missing')),content_hash text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
alter table public.gap_evidence add column if not exists evidence_id uuid references public.evidence(id) on delete cascade;
create table if not exists public.ai_outputs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,ai_run_id uuid not null references public.ai_runs(id) on delete cascade,output_type text not null,schema_version text not null,output_json jsonb not null,reviewer_outcome text check(reviewer_outcome in ('pending','accepted','edited','rejected')),reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.ai_citations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,ai_output_id uuid not null references public.ai_outputs(id) on delete cascade,evidence_id uuid not null references public.evidence(id) on delete restrict,citation_label text,created_at timestamptz not null default now(),unique(ai_output_id,evidence_id));
create table if not exists public.gap_history(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,gap_id uuid not null references public.gaps(id) on delete cascade,actor_user_id uuid references auth.users(id),event text not null,snapshot jsonb not null,created_at timestamptz not null default now());
create table if not exists public.report_snapshots(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,project_id uuid references public.projects(id) on delete cascade,contract_id uuid references public.contracts(id) on delete cascade,report_type text not null check(report_type in ('Gap Register','Executive Report','Contract Diagnostic','Action Register','Obligation Register')),snapshot jsonb not null,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.ai_settings(organization_id uuid primary key references public.organizations(id) on delete cascade,provider text not null default 'openai',main_model text not null default 'gpt-6.1-sol',fast_model text not null default 'gpt-6-luna',reasoning_model text not null default 'gpt-6.1-sol',monthly_cap_usd numeric(12,2),alert_percent integer not null default 80 check(alert_percent between 1 and 100),processing_region text not null default 'Provider regional controls',redact_personal_data boolean not null default true,prompt_log_retention_days integer not null default 90 check(prompt_log_retention_days between 0 and 3650),external_actions_require_approval boolean not null default true,financial_actions_require_approval boolean not null default true,require_source_citations boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
insert into public.ai_settings(organization_id) select id from public.organizations on conflict(organization_id) do nothing;

create index if not exists clauses_contract_idx on public.clauses(contract_id,clause_number);create index if not exists clauses_version_idx on public.clauses(document_version_id);create index if not exists clauses_ai_run_idx on public.clauses(ai_run_id) where ai_run_id is not null;
create index if not exists definitions_contract_idx on public.definitions(contract_id,term);create index if not exists definitions_version_idx on public.definitions(document_version_id);
create index if not exists obligations_contract_idx on public.obligations(contract_id,status);create index if not exists obligations_clause_idx on public.obligations(clause_id) where clause_id is not null;create index if not exists obligations_version_idx on public.obligations(document_version_id);create index if not exists obligations_ai_run_idx on public.obligations(ai_run_id) where ai_run_id is not null;
create index if not exists evidence_org_idx on public.evidence(organization_id,created_at desc);create index if not exists evidence_contract_idx on public.evidence(contract_id) where contract_id is not null;create index if not exists evidence_document_version_idx on public.evidence(document_version_id);create index if not exists evidence_obligation_idx on public.evidence(obligation_id) where obligation_id is not null;create index if not exists gap_evidence_evidence_idx on public.gap_evidence(evidence_id) where evidence_id is not null;
create index if not exists ai_outputs_run_idx on public.ai_outputs(ai_run_id);create index if not exists ai_outputs_org_idx on public.ai_outputs(organization_id,created_at desc);create index if not exists ai_citations_evidence_idx on public.ai_citations(evidence_id);create index if not exists gap_history_gap_idx on public.gap_history(gap_id,created_at desc);create index if not exists gap_history_org_idx on public.gap_history(organization_id,created_at desc);create index if not exists report_snapshots_org_idx on public.report_snapshots(organization_id,created_at desc);

create or replace function private.capture_gap_history() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.gap_history(organization_id,gap_id,actor_user_id,event,snapshot) values(coalesce(new.organization_id,old.organization_id),coalesce(new.id,old.id),auth.uid(),lower(tg_op),case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end);return coalesce(new,old);end$$;
revoke all on function private.capture_gap_history() from public;
drop trigger if exists gaps_history_insert on public.gaps;drop trigger if exists gaps_history_update on public.gaps;drop trigger if exists gaps_history_delete on public.gaps;
create trigger gaps_history_insert after insert on public.gaps for each row execute function private.capture_gap_history();create trigger gaps_history_update after update on public.gaps for each row execute function private.capture_gap_history();

create or replace function private.enforce_gap_review() returns trigger language plpgsql set search_path='' as $$declare v_role public.member_role;begin if new.status is distinct from old.status and new.status in ('Confirmed','Action Required','In Progress','Resolved','Closed') then if not private.can_review_core(new.organization_id) then raise exception 'review permission required for this gap transition';end if;v_role:=private.org_role(new.organization_id);if old.created_by=auth.uid() and v_role not in ('owner','admin') then raise exception 'creator cannot be sole reviewer for a material finding';end if;new.reviewed_by:=auth.uid();new.reviewed_at:=now();end if;new.updated_at:=now();return new;end$$;
drop trigger if exists gaps_review_guard on public.gaps;create trigger gaps_review_guard before update on public.gaps for each row execute function private.enforce_gap_review();

create or replace function private.audit_core_change() returns trigger language plpgsql security definer set search_path='' as $$declare v_org uuid;v_id text;begin v_org:=coalesce((to_jsonb(new)->>'organization_id')::uuid,(to_jsonb(old)->>'organization_id')::uuid);v_id:=coalesce(to_jsonb(new)->>'id',to_jsonb(old)->>'id');insert into public.audit_events(organization_id,actor_user_id,object_type,object_id,action,previous_value,new_value) values(v_org,auth.uid(),tg_table_name,v_id,lower(tg_op),case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end,case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) else null end);return coalesce(new,old);end$$;
revoke all on function private.audit_core_change() from public;
do $$declare t text;begin foreach t in array array['projects','contracts','documents','document_versions','clauses','definitions','obligations','evidence','gaps','actions','report_snapshots'] loop execute format('drop trigger if exists %I on public.%I','audit_'||t,t);execute format('create trigger %I after insert or update or delete on public.%I for each row execute function private.audit_core_change()','audit_'||t,t);end loop;end$$;

alter table public.document_versions enable row level security;alter table public.clauses enable row level security;alter table public.definitions enable row level security;alter table public.obligations enable row level security;alter table public.evidence enable row level security;alter table public.ai_outputs enable row level security;alter table public.ai_citations enable row level security;alter table public.gap_history enable row level security;alter table public.report_snapshots enable row level security;alter table public.ai_settings enable row level security;

