create policy contract_insert on public.contracts for insert to authenticated with check(private.can_manage_core(organization_id));create policy contract_update on public.contracts for update to authenticated using(private.can_manage_core(organization_id)) with check(private.can_manage_core(organization_id));create policy contract_delete on public.contracts for delete to authenticated using(private.can_manage_core(organization_id));
drop policy if exists document_insert on public.documents;drop policy if exists document_update on public.documents;drop policy if exists document_delete on public.documents;
create policy document_insert on public.documents for insert to authenticated with check(private.can_contribute_core(organization_id));create policy document_update on public.documents for update to authenticated using(private.can_contribute_core(organization_id)) with check(private.can_contribute_core(organization_id));create policy document_delete on public.documents for delete to authenticated using(private.can_manage_core(organization_id));
drop policy if exists ai_run_insert on public.ai_runs;create policy ai_run_insert on public.ai_runs for insert to authenticated with check(private.can_contribute_core(organization_id));
drop policy if exists gap_insert on public.gaps;drop policy if exists gap_update on public.gaps;drop policy if exists gap_delete on public.gaps;
create policy gap_insert on public.gaps for insert to authenticated with check(private.can_contribute_core(organization_id));create policy gap_update on public.gaps for update to authenticated using(private.can_contribute_core(organization_id)) with check(private.can_contribute_core(organization_id));
drop policy if exists action_insert on public.actions;drop policy if exists action_update on public.actions;drop policy if exists action_delete on public.actions;
create policy action_insert on public.actions for insert to authenticated with check(private.can_contribute_core(organization_id));create policy action_update on public.actions for update to authenticated using(private.can_contribute_core(organization_id)) with check(private.can_contribute_core(organization_id));create policy action_delete on public.actions for delete to authenticated using(private.can_manage_core(organization_id));
drop policy if exists audit_insert on public.audit_events;revoke insert on public.audit_events from authenticated;revoke delete on public.gaps from authenticated;

