create policy definitions_select on public.definitions for select to authenticated using(private.is_org_member(organization_id));create policy definitions_insert on public.definitions for insert to authenticated with check(private.can_contribute_core(organization_id));create policy definitions_delete on public.definitions for delete to authenticated using(private.can_contribute_core(organization_id));
