create or replace function private.sync_document_current_version() returns trigger language plpgsql security definer set search_path='' as $$begin if new.is_current then update public.document_versions set is_current=false where document_id=new.document_id and id<>new.id and is_current;update public.documents set current_version_id=new.id,version_no=new.version_no,storage_path=new.storage_path,file_name=new.file_name,content_hash=new.content_hash,processing_status=new.processing_status where id=new.document_id;end if;return new;end$$;
revoke all on function private.sync_document_current_version() from public;drop trigger if exists document_versions_sync_current on public.document_versions;create trigger document_versions_sync_current after insert or update of is_current,processing_status on public.document_versions for each row execute function private.sync_document_current_version();
